# OneDrive API Integration - Apideck
created: 2026-06-11, last updated: 2026-06-12, [Read more](https://www.apideck.com/integrations/onedrive)

const apideck = new Apideck({
apiKey: process.env.APIDECK_API_KEY,
appId: process.env.APIDECK_APP_ID,
consumerId: 'user-123'
})
// List files from OneDrive
const { data } = await apideck.file-storage.filesAll({
serviceId: 'onedrive'
})
console.log(`Found ${data.length} files`)

